-- ===========================================================================
-- CARRIER BOOKING ON THE SCHEDULE — client request, 2026-10-28
-- ===========================================================================
--
-- The Vessel / Flight schedule form gains the carrier's booking no and a
-- file (usually the carrier's booking confirmation). Both optional.
--
-- Affects one existing table, shipment_schedule: two nullable columns, so
-- every existing version is valid as it stands. Its audit trigger, RLS and
-- grants already cover new columns. The DDL was generated by `prisma migrate
-- diff`; the CHECK below it is hand-written.
-- ===========================================================================

-- AlterTable
ALTER TABLE "shipment_schedule" ADD COLUMN     "booking_file" TEXT,
ADD COLUMN     "carrier_booking_no" VARCHAR(64);



-- ---------------------------------------------------------------- integrity
ALTER TABLE "shipment_schedule" ADD CONSTRAINT "shipment_schedule_carrier_booking_no_not_blank"
  CHECK ("carrier_booking_no" IS NULL OR length(btrim("carrier_booking_no")) > 0);
